('bass','BASS','Burning and Suppression of Solids','BASS','solid',15,21,101,101,0,50,ARRAY['prevention','suppression']::text[],0.95,'{"id":"bass","acronym":"BASS","name":"Burning and Suppression of Solids","project":"BASS","hardware":"MSG-SPICE duct","platform":"ISS – Microgravity Science Glovebox","years":"2011–2012","fuelType":"solid","fuels":["PMMA (acrylic)","Cotton–fiberglass fabric (SIBAL)","Delrin","Candle wax"],"sampleGeometry":"Flat sheets, cylinders, spheres; ~1–10 cm","o2":[15,21],"pressure":[101,101],"flow":[0,50],"diluents":["N₂ (via flow reduction / chamber dilution)"],"sensors":["Color video (2 views)","Thermocouples","Radiometer","Flow meter"],"objective":"Determine how solid materials ignite, spread flame and extinguish in microgravity as a function of airflow and geometry.","variables":"Sample material, geometry and thickness; forced airflow speed; N₂ dilution for suppression.","findings":["Many solids burn in microgravity at lower flow speeds than expected from Earth tests — low ventilation does not mean safety.","Flames in µg are dimmer, slower and closer to the surface, so they can be harder to see.","Reducing airflow alone can extinguish a flame, but only below a material-specific limit."],"categories":["prevention","suppression"],"directness":0.95,"habitatNote":"Core materials-flammability data for cabin materials under realistic ventilation flows.","earthApplication":"Improves understanding of flame spread over plastics and fabrics in low-flow building fires.","dataConfidence":"approximate","psiQuery":"BASS"}'::jsonb),
('bass-ii','BASS-II','Burning and Suppression of Solids – II','BASS','solid',14,21,101,101,0,50,ARRAY['prevention','suppression']::text[],1,'{"id":"bass-ii","acronym":"BASS-II","name":"Burning and Suppression of Solids – II","project":"BASS","hardware":"MSG-SPICE duct","platform":"ISS – Microgravity Science Glovebox","years":"2012–2013","fuelType":"solid","fuels":["PMMA","Cotton–fiberglass fabric","Polyethylene","Delrin"],"sampleGeometry":"Thin and thick flat samples, cylinders; ~1–10 cm","o2":[14,21],"pressure":[101,101],"flow":[0,50],"diluents":["N₂"],"sensors":["Color video","Thermocouples","Radiometer","O₂ sensor"],"objective":"Extend BASS to map limiting oxygen concentration and flow for flame spread and extinction of solids.","variables":"O₂ concentration (via N₂ dilution), flow speed, sample thickness, material.","findings":["Microgravity limiting O₂ for some materials is lower than the NASA-STD-6001 1-g upward test predicts.","There is a flow speed that makes materials most flammable; both lower and higher flows weaken the flame.","Thin fuels spread flame steadily; thick fuels approach a near-steady spread rate after transition."],"categories":["prevention","suppression"],"directness":1,"habitatNote":"Directly informs material selection margins for elevated-O₂ Moon Base and rover cabins.","earthApplication":"Better flammability test standards for aircraft and submarine cabins.","dataConfidence":"approximate","psiQuery":"BASS-II"}'::jsonb),
('saffire-1','Saffire-I','Spacecraft Fire Safety Demonstration I','Saffire','solid',21,21,101,101,20,25,ARRAY['prevention','detection']::text[],1,'{"id":"saffire-1","acronym":"Saffire-I","name":"Spacecraft Fire Safety Demonstration I","project":"Saffire","hardware":"Cygnus (Saffire)","platform":"Cygnus cargo vehicle after ISS departure","years":"2016","fuelType":"solid","fuels":["Cotton–fiberglass fabric (SIBAL)"],"sampleGeometry":"Large sheet ~41 × 94 cm","o2":[21,21],"pressure":[101,101],"flow":[20,25],"diluents":[],"sensors":["HD video (2 views)","Thermocouples","Radiometers","O₂ & CO₂ sensors","Pressure transducer"],"objective":"First large-scale fire in a spacecraft: measure flame growth and spread over a large fabric sheet.","variables":"Single large sample; concurrent airflow direction.","findings":["Large-scale flames grew and spread steadily for minutes without self-extinguishing.","Flame spread rates over large samples differ from small-scale lab predictions.","Pressure and O₂ change in the vehicle validated fire-scenario models."],"categories":["prevention","detection"],"directness":1,"habitatNote":"The only realistic-scale spacecraft fire data — key for fire-scenario modelling of habitats.","dataConfidence":"approximate","psiQuery":"Saffire"}'::jsonb),
('saffire-2','Saffire-II','Spacecraft Fire Safety Demonstration II','Saffire','solid',21,21,101,101,20,25,ARRAY['prevention']::text[],0.95,'{"id":"saffire-2","acronym":"Saffire-II","name":"Spacecraft Fire Safety Demonstration II","project":"Saffire","hardware":"Cygnus (Saffire)","platform":"Cygnus cargo vehicle after ISS departure","years":"2016","fuelType":"solid","fuels":["Nomex","Silicone","PMMA","Cotton–fiberglass","Kydex","Spacesuit materials"],"sampleGeometry":"Nine samples ~5 × 29 cm","o2":[21,21],"pressure":[101,101],"flow":[20,25],"diluents":[],"sensors":["HD video","Thermocouples","Radiometers","Gas analysers"],"objective":"Ignite nine different spacecraft materials to compare ignition and flammability in microgravity.","variables":"Material type and thickness; same flow and atmosphere.","findings":["Material rankings in µg do not always match 1-g screening rankings.","Some materials judged non-flammable on Earth still sustained flames in low flow."],"categories":["prevention"],"directness":0.95,"habitatNote":"Direct materials comparison relevant to cabin and spacesuit material choice.","dataConfidence":"approximate","psiQuery":"Saffire"}'::jsonb),
('saffire-3','Saffire-III','Spacecraft Fire Safety Demonstration III','Saffire','solid',21,21,101,101,10,25,ARRAY['prevention','detection']::text[],1,'{"id":"saffire-3","acronym":"Saffire-III","name":"Spacecraft Fire Safety Demonstration III","project":"Saffire","hardware":"Cygnus (Saffire)","platform":"Cygnus cargo vehicle after ISS departure","years":"2017","fuelType":"solid","fuels":["Cotton–fiberglass fabric (SIBAL)"],"sampleGeometry":"Large sheet ~41 × 94 cm","o2":[21,21],"pressure":[101,101],"flow":[10,25],"diluents":[],"sensors":["HD video","Thermocouples","Radiometers","O₂/CO₂ sensors","Smoke particle sensors"],"objective":"Repeat large-scale burn with varied flow to quantify spread and the effect on the vehicle environment.","variables":"Airflow speed; flame spread direction.","findings":["Lower flow speeds slowed but did not stop large-scale spread.","Combustion products and particulates were measured for post-fire atmosphere recovery."],"categories":["prevention","detection"],"directness":1,"habitatNote":"Ventilation effect on real-scale fire — informs whether shutting fans helps suppress a fire.","dataConfidence":"approximate","psiQuery":"Saffire"}'::jsonb),
('same','SAME','Smoke and Aerosol Measurement Experiment','SAME','aerosol',21,21,101,101,0,5,ARRAY['detection']::text[],0.9,'{"id":"same","acronym":"SAME","name":"Smoke and Aerosol Measurement Experiment","project":"SAME","hardware":"MSG","platform":"ISS – Microgravity Science Glovebox","years":"2007–2008","fuelType":"aerosol","fuels":["Teflon","Kapton","Silicone rubber","Cellulose (lamp wick)","Dibutyl phthalate"],"sampleGeometry":"Small heated (smouldering) samples","o2":[21,21],"pressure":[101,101],"flow":[0,5],"diluents":[],"sensors":["Ionization detector","Photoelectric detector","DustTrak","P-Trak","Thermal precipitator"],"objective":"Measure particle size of smoke from overheated spacecraft materials to design better smoke detectors.","variables":"Material type, heating rate/temperature, aging time.","findings":["Smoke particles in µg are generally larger than on Earth because they age without settling.","Existing ISS photoelectric detectors could miss smoke from some materials."],"categories":["detection"],"directness":0.9,"habitatNote":"Defines what smoke looks like to a detector in a sealed habitat.","earthApplication":"Detector designs that discriminate smoke from dust reduce nuisance alarms in mining and industry.","dataConfidence":"approximate","psiQuery":"SAME"}'::jsonb),
