('flex','FLEX','Flame Extinguishment Experiment','FLEX','liquid',12,40,50,101,0,0,ARRAY['suppression','fundamentals']::text[],0.9,'{"id":"flex","acronym":"FLEX","name":"Flame Extinguishment Experiment","project":"FLEX","hardware":"CIR-MDCA","platform":"ISS – Combustion Integrated Rack","years":"2009–2012","fuelType":"liquid","fuels":["n-Heptane","Methanol","Methanol/water"],"sampleGeometry":"Free-floating droplets 1–5 mm","o2":[12,40],"pressure":[50,101],"flow":[0,0],"diluents":["CO₂","He","N₂"],"sensors":["Backlit droplet camera","Color flame camera","UV OH* imaging","Radiometer"],"objective":"Find the diluent concentrations that extinguish burning droplets, to choose spacecraft fire suppressants.","variables":"Fuel, droplet size, O₂ %, diluent type (CO₂ vs He), pressure.","findings":["Discovered heptane ''cool flames'' that keep burning invisibly after the hot flame goes out.","CO₂ is less effective at suppression in µg than expected; He behaves differently from 1-g.","Larger droplets reach radiative extinction — size matters for suppression."],"categories":["suppression","fundamentals"],"directness":0.9,"habitatNote":"Primary source for CO₂ vs inert-gas suppression choices in spacecraft.","earthApplication":"Cool-flame chemistry improves engine and fuel-safety models.","dataConfidence":"approximate","psiQuery":"FLEX"}'::jsonb),
