('cfi','CFI','Cool Flames Investigation','FLEX','liquid',15,40,100,300,0,0,ARRAY['fundamentals','detection']::text[],0.55,'{"id":"cfi","acronym":"CFI","name":"Cool Flames Investigation","project":"FLEX","hardware":"CIR-MDCA","platform":"ISS – Combustion Integrated Rack","years":"2017–2019","fuelType":"liquid","fuels":["n-Heptane","n-Octane","n-Decane","n-Dodecane"],"sampleGeometry":"Droplets 2–5 mm","o2":[15,40],"pressure":[100,300],"flow":[0,0],"diluents":["N₂","CO₂","He"],"sensors":["Droplet camera","Color camera","Radiometer"],"objective":"Characterise low-temperature ''cool flame'' burning of liquid fuels discovered in FLEX.","variables":"Fuel, pressure, O₂, diluent.","findings":["Cool flames burn at ~500–800 K and are nearly invisible — a hidden hazard for detection.","Cool-flame regime widens with pressure and O₂."],"categories":["fundamentals","detection"],"directness":0.55,"habitatNote":"Shows a fire may persist after it ''looks'' extinguished — affects post-fire procedures.","dataConfidence":"approximate","psiQuery":"Cool Flames"}'::jsonb),
